import arcjet, { fixedWindow } from "@arcjet/next";

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [fixedWindow({ mode: "LIVE", window: "1m", max: 5 })],
});

export async function GET(req: Request) {
  const decision = await aj.protect(req);

  if (decision.conclusion === "DENY") {
    if (decision.reason.isRateLimit()) {
      return new Response("Too many requests", { status: 429 });
    }
    return new Response("Forbidden", { status: 403 });
  }

  if (decision.conclusion === "CHALLENGE") {
    return new Response("Challenge required", { status: 401 });
  }

  if (decision.conclusion === "ERROR") {
    return new Response("Protection error", { status: 503 });
  }

  return new Response("OK");
}

import arcjet, { detectBot, createCustomRule, decision } from "@arcjet/next";

const customRule = createCustomRule({
  name: "business-hours",
  evaluate: ({ ip }) => {
    const hour = new Date().getUTCHours();
    return hour >= 9 && hour < 17 ? decision.ALLOW : decision.DENY;
  },
});

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [detectBot({ mode: "LIVE" }), customRule],
});

