import { createArcjet, detectBot } from "@arcjet/node";
import { z } from "zod";

const aj = createArcjet({ key: process.env.ARCJET_KEY! });

const bodyRule = {
  type: "CUSTOM",
  validate: async ({ request }) => {
    const body = await request.json();
    return z.object({ email: z.string().email() }).safeParse(body).success;
  },
};

const decision = await aj
  .withRule(bodyRule)
  .protect(request);

if (decision.isDenied()) {
  return new Response("Forbidden", { status: 403 });
}
return new Response("OK");

import arcjet, { validateEmail } from "@arcjet/next";

const aj = arcjet({
  key: process.env.ARCJET_KEY!,
  rules: [
    validateEmail({
      mode: "LIVE",
      deny: ["DISPOSABLE", "INVALID", "NO_MX_RECORDS"],
    }),
  ],
});

export async function POST(req: Request) {
  const { email } = await req.json();
  const decision = await aj.protect(req, { email });
  return decision.isDenied()
    ? new Response("Invalid email", { status: 400 })
    : new Response("Accepted", { status: 200 });
}

